WITH enriched AS (SELECT id, product_id, quantity, last_restock, MIN(quantity) OVER w_recent AS last4_min_quantity, MAX(quantity) OVER w_recent AS last4_max_quantity, SUM(quantity) OVER w_recent AS last4_sum_quantity, COUNT(quantity) OVER w_recent AS last4_count_quantity FROM inventory WINDOW w_recent AS (PARTITION BY store_id, product_id ORDER BY last_restock, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)) SELECT DATE_TRUNC('WEEK', last_restock) AS week_start, COUNT(DISTINCT product_id) AS distinct_product_ids, ROUND(AVG(last4_max_quantity), 2) AS avg_last4_max_quantity FROM enriched GROUP BY ROLLUP (DATE_TRUNC('WEEK', last_restock));
